import re

def eval_expression(expr):
    # 1. トークナイズ: 数字（小数含む）、演算子、括弧を抽出
    tokens = re.findall(r'\d+\.?\d*|[+\-*/()]', expr)
    pos = 0

    def peek():
        """現在のトークンを覗き見る"""
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        """現在のトークンを消費して次に進む"""
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        """加算と減算を処理 (優先度 最低)"""
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        """乗算と除算を処理 (優先度 中)"""
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        """単項演算子（正負）と括弧、数値を処理 (優先度 最高)"""
        token = peek()
        if token == '+':
            consume()
            return parse_factor()
        if token == '-':
            consume()
            return -parse_factor()
        if token == '(':
            consume() # '(' を消費
            result = parse_expression()
            consume() # ')' を消費
            return result

        # 数値の処理
        return float(consume())

    # 計算開始
    return parse_expression()

# --- テストケース ---
test_cases = [
    ("3 + 4 * (2 - 1)", 7.0),
    ("10 + 2 * 3", 16.0),
    ("-5 + 2", -3.0),
    ("-(3 + 2) * 2", -10.0),
    ("10 / (2 + 3)", 2.0),
    ("2.5 * 2", 5.0),
]

for exp, expected in test_cases:
    result = eval_expression(exp)
    print(f"'{exp}' => {result} (Expected: {expected})")

# ゼロ除算のテスト
try:
    eval_expression("10 / 0")
except ZeroDivisionError as e:
    print(f"Caught expected error: {e}")
